      en: ["Completed in 1968.", "Has a capacity of 42,000 worshippers.", "Its design is similar to the Kaaba."],
      es: ["Terminada en 1968.", "Capacidad para 42.000 fieles.", "Arquitectura similar a la Kaaba."],
      pt: ["Concluída em 1968.", "Capacidade para 42.000 fiéis.", "Arquitetura semelhante à Kaaba."],
