      pt: ["Nomeada em honra de Lord Hardinge, Vice-Rei da Índia", "Inaugurada para o tráfego ferroviário em 1915", "Uma das pontes ferroviárias mais longas do país", "Ligação importante entre o norte e o sul do Bangladesh"],
