      de: ["1913 als Dhaka Museum gegründet.", "Das größte Museum in Bangladesch.", "Umfasst zahlreiche Abteilungen."],
      hu: ["1913-ban alapították Dakka Múzeum néven.", "Banglades legnagyobb múzeuma.", "Számos különböző részleggel rendelkezik."],
      ro: ["Fondat în 1913 sub numele de Muzeul Dhaka.", "Cel mai mare muzeu din Bangladesh.", "Include numeroase departamente."],
